    "markdown \"",
  "              \"AGENT ID | delete AGENT ID AGENTS RESUMED\", file=sys.stderr)",
  "        return 2",
  "    print(json.dumps(answer))",
  "    return 0",
  "",
  "",
  "if __name__ == \"__main__\":",
  "    sys.exit(main(sys.argv))",
  "",
